  /// < MTP have not any device
  static const int MTP_ERROR_NO_DEVICE = -30146557;

  /// < MTP is not initialized
  static const int MTP_ERROR_NOT_INITIALIZED = -30146556;

  /// < MTP is not activated
  static const int MTP_ERROR_NOT_ACTIVATED = -30146555;

  /// < MTP communication is not initialized
  static const int MTP_ERROR_NOT_COMM_INITIALIZED = -30146554;

